package dev.agentroid.helper.runner;

import dev.agentroid.helper.core.Json;
import dev.agentroid.helper.link.net.LinkCrypto;

import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The Rust hub's fixtures (schemas/fixtures/segment, generated by crates/segments/src/fixtures.rs) checked on the
 * phone side: identical canonical bytes, Rust signatures verify with the pinned test hub key, tampering fails, and
 * each fixture gets the outcome canonical.json expects.
 */
public final class SegmentFixturesTest {
    @SuppressWarnings("unchecked")
    static Map<String, Object> doc() throws Exception {
        return (Map<String, Object>) Json.parse(A.read(A.fixtures().resolve("canonical.json")));
    }

    @SuppressWarnings("unchecked")
    static List<Map<String, Object>> cases() throws Exception {
        return (List<Map<String, Object>>) doc().get("cases");
    }

    static byte[] spki() throws Exception { return Base64.getDecoder().decode((String) doc().get("hub_spki")); }

    static String hex(byte[] b) {
        StringBuilder s = new StringBuilder();
        for (byte x : b) s.append(String.format("%02x", x & 0xff));
        return s.toString();
    }

    /** A runner whose trust store pins the fixtures' test hub key, at the fixtures' "now". */
    static final class FixtureRig {
        final FakeClock clock;
        final Fakes.Trust trust;
        final Fakes.Executor exec;
        final Fakes.Journal journal = new Fakes.Journal();
        final Fakes.Done done;
        final SegmentRunner runner;
        final SegmentVerifier verifier;

        FixtureRig(byte[] spki) throws Exception {
            Map<String, Object> d = doc();
            clock = new FakeClock(Instant.parse((String) d.get("now")).toEpochMilli());
            trust = new Fakes.Trust(spki, (String) d.get("device"), ((Long) d.get("epoch")).longValue());
            exec = new Fakes.Executor(clock, 200);
            done = new Fakes.Done(clock);
            verifier = new SegmentVerifier(trust, clock);
            runner = new SegmentRunner(clock, verifier, SafeClasses.bundled(), exec, new Fakes.Touch(), journal,
                    new ReportOutbox(new Fakes.Transport(true)), true, done);
        }
    }

    public void testCanonicalBytesMatchTheRustHubForEveryFixture() throws Exception {
        Map<String, Object> d = doc();
        A.eq(Canonical.DOMAIN, d.get("domain"), "domain label");
        A.eq(LinkCrypto.keyId(spki()), d.get("hub_key_id"), "key id = SHA-256 of the SPKI, as the link computes it");
        int n = 0;
        for (Map<String, Object> c : cases()) {
            String name = (String) c.get("fixture");
            Map<String, Object> env = (Map<String, Object>) Json.parse(A.read(A.fixtures().resolve(name)));
            Map<String, Object> seg = (Map<String, Object>) env.get("segment");
            A.eq(c.get("canonical"), Canonical.write(seg), name + ": canonical text");
            byte[] sha = MessageDigest.getInstance("SHA-256").digest(Canonical.signedBytes(seg));
            A.eq(c.get("signed_bytes_sha256"), hex(sha), name + ": signed bytes");
            n++;
        }
        A.ok(n >= 8, "at least 8 fixtures, got " + n);
    }

    public void testThePhoneVerifiesEveryRustSignature() throws Exception {
        for (Map<String, Object> c : cases()) {
            String name = (String) c.get("fixture");
            FixtureRig r = new FixtureRig(spki());
            Segment s = r.verifier.verify(A.read(A.fixtures().resolve(name)));
            A.ok(s.steps.size() >= 1, name);
        }
    }

    public void testEachFixtureGetsTheExpectedOutcomeEndToEnd() throws Exception {
        for (Map<String, Object> c : cases()) {
            String name = (String) c.get("fixture");
            String expect = (String) c.get("expect");
            FixtureRig r = new FixtureRig(spki());
            r.runner.submit(A.read(A.fixtures().resolve(name)));
            r.clock.runIdle(10 * 60_000L);
            Map<String, Object> rep = (Map<String, Object>) Json.parse(r.done.report);
            if (expect.equals("ok")) {
                A.eq("completed", r.done.outcome, name + ": " + r.done.report);
                for (Object o : (List<Object>) rep.get("steps")) A.eq(Boolean.TRUE, ((Map<String, Object>) o).get("post_verified"), name + " post verified");
            } else {
                A.eq("refused", r.done.outcome, name);
                A.eq(expect, rep.get("reason"), name);
                A.eq(0, r.exec.acts.size(), name + ": nothing acted");
            }
        }
    }

    public void testATamperedFixtureFails() throws Exception {
        int checked = 0;
        for (Map<String, Object> c : cases()) {
            String name = (String) c.get("fixture");
            String text = A.read(A.fixtures().resolve(name));
            List<String> tampered = new ArrayList<String>();
            tampered.add(text.replace("\"epoch\":7", "\"epoch\":8"));
            tampered.add(text.replace("\"steps\":[{\"id\":\"", "\"steps\":[{\"id\":\"X"));
            tampered.add(text.contains("\"owned\":false") ? text.replace("\"owned\":false", "\"owned\":true") : text.replace("\"owned\":true", "\"owned\":false"));
            tampered.add(text.replace("2026-10-20T12:30:00Z", "2026-10-20T12:45:00Z"));
            // flip one bit of the signature's last DER byte
            Map<String, Object> env = (Map<String, Object>) Json.parse(text);
            Map<String, Object> sig = (Map<String, Object>) env.get("signature");
            byte[] der = Base64.getDecoder().decode((String) sig.get("value"));
            der[der.length - 1] ^= 1;
            Map<String, Object> sig2 = new LinkedHashMap<String, Object>(sig);
            sig2.put("value", Base64.getEncoder().encodeToString(der));
            env.put("signature", sig2);
            tampered.add(Json.write(env));
            for (String t : tampered) {
                A.ok(!t.equals(text), name + ": the tamper changed something");
                FixtureRig r = new FixtureRig(spki());
                r.trust.epoch = t.contains("\"epoch\":8") ? 8 : 7; // so only the signature can catch an epoch edit
                SegmentRefused e = A.throwsA(SegmentRefused.class, () -> r.verifier.verify(t), name + " tampered");
                A.eq("bad_signature", e.code, name + ": " + e.getMessage());
                checked++;
            }
        }
        A.ok(checked >= 40, "tampered variants checked: " + checked);
    }

    public void testAnotherHubKeyOrNoPairingIsRefused() throws Exception {
        String text = A.read(A.fixtures().resolve("valid-r0.json"));
        FixtureRig other = new FixtureRig(new TestHub("x", 7).spki());
        A.eq("wrong_hub_key", A.throwsA(SegmentRefused.class, () -> other.verifier.verify(text), "other key").code, "other key");
        FixtureRig none = new FixtureRig(spki());
        none.trust.spki = null;
        A.eq("hub_key_missing", A.throwsA(SegmentRefused.class, () -> none.verifier.verify(text), "unpaired").code, "unpaired");
        A.eq(0, none.trust.writes, "the runner never writes the link's trust store");
    }

    public void testEveryInvalidFixtureIsRefused() throws Exception {
        int n = 0;
        DirectoryStream<Path> ds = Files.newDirectoryStream(A.fixtures(), "invalid-*.json");
        try {
            for (Path p : ds) {
                final String text = A.read(p);
                FixtureRig r = new FixtureRig(spki());
                A.throwsA(SegmentRefused.class, () -> r.verifier.verify(text), p.getFileName().toString());
                n++;
            }
        } finally {
            ds.close();
        }
        A.ok(n >= 10, "invalid fixtures: " + n);
    }

    public void testCanonicalJavaSideRules() throws Exception {
        Map<String, Object> m = new LinkedHashMap<String, Object>();
        m.put("b", Long.valueOf(1));
        m.put("�", "r");          // UTF-8 EF BF BD
        m.put("😀", "e");    // U+1F600, UTF-8 F0 9F 98 80: after U+FFFD in UTF-8 order (before it in UTF-16 order)
        m.put("A", Boolean.TRUE);
        A.eq("{\"A\":true,\"b\":1,\"�\":\"r\",\"😀\":\"e\"}", Canonical.write(m), "keys sorted by UTF-8 bytes");
        A.eq("\"\\u0001\\u001f\\b\\t\\n\\f\\r\\\"\\\\/\u007f\"", Canonical.write("\u0001\u001f\b\t\n\f\r\"\\/\u007f"), "escapes");
        A.throwsA(IllegalArgumentException.class, () -> Canonical.write(Double.valueOf(1.5)), "floats refused");
        A.throwsA(IllegalArgumentException.class, () -> Canonical.write("\uD83D"), "lone surrogate refused");
        A.eq(String.valueOf(Long.MIN_VALUE), Canonical.write(Long.valueOf(Long.MIN_VALUE)), "i64 min");
    }
}
